//! Song library on disk: `<app data>/songs/<id>.audio` (the user's file, as is)
//! and `<id>.json` (analysis + metadata, written by the frontend).

use std::fs;
use std::path::PathBuf;
use tauri::ipc::{InvokeBody, Request, Response};
use tauri::{AppHandle, Manager};

fn songs_dir(app: &AppHandle) -> Result<PathBuf, String> {
    let dir = app.path().app_data_dir().map_err(|e| e.to_string())?.join("songs");
    fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    Ok(dir)
}

/// Ids are generated by the app; reject anything that could escape the folder.
fn check_id(id: &str) -> Result<&str, String> {
    let ok = !id.is_empty()
        && id.len() <= 64
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if ok { Ok(id) } else { Err("invalid song id".into()) }
}

/// Raw body: the audio file bytes. Header `x-song-id` names the song.
#[tauri::command]
pub fn song_save_audio(app: AppHandle, request: Request<'_>) -> Result<(), String> {
    let id = request
        .headers()
        .get("x-song-id")
        .and_then(|v| v.to_str().ok())
        .ok_or("missing x-song-id header")?;
    let id = check_id(id)?;
    let InvokeBody::Raw(bytes) = request.body() else {
        return Err("expected raw audio bytes".into());
    };
    fs::write(songs_dir(&app)?.join(format!("{id}.audio")), bytes).map_err(|e| e.to_string())
}

#[tauri::command]
pub fn song_load_audio(app: AppHandle, id: String) -> Result<Response, String> {
    let id = check_id(&id)?;
    let bytes = fs::read(songs_dir(&app)?.join(format!("{id}.audio"))).map_err(|e| e.to_string())?;
    Ok(Response::new(bytes))
}

#[tauri::command]
pub fn song_save_meta(app: AppHandle, id: String, meta: String) -> Result<(), String> {
    let id = check_id(&id)?;
    fs::write(songs_dir(&app)?.join(format!("{id}.json")), meta).map_err(|e| e.to_string())
}

#[tauri::command]
pub fn song_read_meta(app: AppHandle, id: String) -> Result<String, String> {
    let id = check_id(&id)?;
    fs::read_to_string(songs_dir(&app)?.join(format!("{id}.json"))).map_err(|e| e.to_string())
}

/// All song metadata JSON strings (unordered).
#[tauri::command]
pub fn song_list(app: AppHandle) -> Result<Vec<String>, String> {
    let mut out = Vec::new();
    for entry in fs::read_dir(songs_dir(&app)?).map_err(|e| e.to_string())? {
        let path = entry.map_err(|e| e.to_string())?.path();
        if path.extension().is_some_and(|e| e == "json") {
            if let Ok(s) = fs::read_to_string(&path) {
                out.push(s);
            }
        }
    }
    Ok(out)
}

#[tauri::command]
pub fn song_delete(app: AppHandle, id: String) -> Result<(), String> {
    let id = check_id(&id)?;
    let dir = songs_dir(&app)?;
    for ext in ["audio", "json"] {
        let p = dir.join(format!("{id}.{ext}"));
        if p.exists() {
            fs::remove_file(p).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}
